mapper.select:
SELECT TO_CHAR(handle_time, #{timeType}) AS time, type, COALESCE(SUM(quantity), 0) AS quantity FROM bbx_restaurant_waste_record WHERE handle_time >= #{minDay} AND handle_time <= #{maxDay} AND type IS NOT NULL AND quantity IS NOT NULL AND quantity >= 0 AND deleted = 1
and tenant_id =#{tenantId}
GROUP BY TO_CHAR(handle_time, #{timeType}), type
